import{_ as r,o as a,c as t,ai as l}from"./chunks/framework.iNbpOH0p.js";const f=JSON.parse('{"title":"状态管理与路由","description":"","frontmatter":{},"headers":[],"relativePath":"doc/awesome-vue/状态管理与路由.md","filePath":"doc/awesome-vue/状态管理与路由.md"}'),i={name:"doc/awesome-vue/状态管理与路由.md"};function o(n,e,u,h,s,c){return a(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="状态管理与路由" tabindex="-1">状态管理与路由 <a class="header-anchor" href="#状态管理与路由" aria-label="Permalink to “状态管理与路由”">​</a></h1><h2 id="状态管理库" tabindex="-1">状态管理库 <a class="header-anchor" href="#状态管理库" aria-label="Permalink to “状态管理库”">​</a></h2><ul><li><a href="https://github.com/pmndrs/zustand" target="_blank" rel="noreferrer">Zustand</a> ⭐ 57.7k — 轻量级状态管理库，基于简化 Flux 原则，提供简洁的 API 和无样板代码的开发体验，可通过适配器用于 Vue</li><li><a href="https://github.com/vuejs/vuex" target="_blank" rel="noreferrer">Vuex</a> ⭐ 28k — Vue 经典状态管理库，提供集中式状态存储和变更管理，支持插件系统、严格模式和 SSR 状态序列化，是 Vue 2 时代的官方状态管理方案（已迁移至 Pinia）</li><li><a href="https://github.com/mobxjs/mobx" target="_blank" rel="noreferrer">MobX</a> ⭐ 28k — 简单、可扩展的状态管理库，通过响应式编程自动追踪状态变化，可与 Vue 集成使用，提供透明函数式响应式编程体验</li><li><a href="https://github.com/pmndrs/jotai" target="_blank" rel="noreferrer">Jotai</a> ⭐ 17k — 原子化状态管理库，支持 Vue 集成，采用自底向上的状态构建方式，提供细粒度的状态更新和出色的开发体验</li><li><a href="https://github.com/vuejs/pinia" target="_blank" rel="noreferrer">Pinia</a> ⭐ 14.3k — Vue 官方推荐的新一代状态管理库，替代 Vuex，提供直观的 API、完整的 TypeScript 支持和 DevTools 集成，支持模块化设计</li><li><a href="https://github.com/pmndrs/valtio" target="_blank" rel="noreferrer">Valtio</a> ⭐ 9.5k — 基于 Proxy 的响应式状态管理库，支持 Vue 集成，提供简单的状态定义和自动依赖追踪，适合中小型项目</li><li><a href="https://github.com/effector/effector" target="_blank" rel="noreferrer">Effector</a> ⭐ 6.5k — 业务逻辑管理器，提供状态管理、事件驱动架构和副作用处理，支持 Vue 集成，具有优秀的 TypeScript 类型推断</li><li><a href="https://github.com/nanostores/nanostores" target="_blank" rel="noreferrer">Nanostores</a> ⭐ 2.5k — 超轻量级状态管理库（仅 338 字节），支持 Vue 集成，提供类型安全的原子状态和计算状态</li><li><a href="https://github.com/wobsoriano/vue-zustand" target="_blank" rel="noreferrer">vue-zustand</a> ⭐ 2.1k — Zustand 的 Vue 移植版本，基于简化 Flux 原则的轻量级状态管理方案，提供简洁的 API 和无样板代码的开发体验</li><li><a href="https://github.com/cerebral/overmind" target="_blank" rel="noreferrer">Overmind</a> ⭐ 1.4k — 直观且强大的状态管理方案，支持 Vue 集成，提供声明式状态定义、副作用管理和强大的 DevTools 调试支持</li><li><a href="https://github.com/storeon/storeon" target="_blank" rel="noreferrer">Storeon</a> ⭐ 1.1k — 轻量级事件驱动状态管理器，仅 338 字节，支持 Vue 集成，采用模块化架构和 Redux 风格的状态管理模式</li><li><a href="https://github.com/TanStack/query" target="_blank" rel="noreferrer">TanStack Query (Vue)</a> ⭐ 50k — 服务端状态管理之王，内置 @tanstack/vue-query 一等公民支持，提供缓存、去重、乐观更新、后台重新获取等能力</li><li><a href="https://github.com/andrewcourtice/harlem" target="_blank" rel="noreferrer">harlem</a> ⭐ 515 — 简洁、轻量、可扩展的 Vue3 全局状态管理库，基于 Composition API 与模块化 store 设计，无额外依赖，DevTools 支持良好。</li></ul><h2 id="路由管理" tabindex="-1">路由管理 <a class="header-anchor" href="#路由管理" aria-label="Permalink to “路由管理”">​</a></h2><ul><li><a href="https://github.com/vuejs/router" target="_blank" rel="noreferrer">Vue Router</a> ⭐ 4.6k — Vue 官方路由管理器，支持嵌套路由、动态路由匹配、路由参数、路由守卫、懒加载和完整的导航控制</li><li><a href="https://github.com/posva/unplugin-vue-router" target="_blank" rel="noreferrer">unplugin-vue-router</a> ⭐ 3.2k — 基于文件系统的路由生成器，自动根据目录结构生成路由配置，支持约定式路由和类型安全</li><li><a href="https://github.com/antfu/vue-router-better-scroller" target="_blank" rel="noreferrer">vue-router-better-scroller</a> ⭐ 1.8k — Vue Router v4 滚动行为增强插件，支持多滚动容器状态保持、平滑滚动和自定义滚动策略</li><li><a href="https://github.com/zack24q/vue-navigation" target="_blank" rel="noreferrer">vue-navigation</a> ⭐ 1.0k — 页面导航库，记录路由并缓存页面，提供类似原生 APP 的页面导航体验，支持前进、后退、替换等导航行为</li><li><a href="https://github.com/sparklinm/vue-router-cache-animate" target="_blank" rel="noreferrer">vue-router-cache-animate</a> ⭐ 800 — 为 Vue Router 提供快速自定义缓存和动画的插件，支持页面级缓存控制和过渡动画配置</li><li><a href="https://github.com/githubzhuangye/vue-router-dynamic-cache" target="_blank" rel="noreferrer">vue-router-dynamic-cache</a> ⭐ 600 — 基于 Vue Router 和 Vuex 的 SPA 路由组件动态缓存策略，无需修改源码即可实现前进刷新、后退缓存的原生应用体验</li><li><a href="https://github.com/hannoeru/vite-plugin-pages" target="_blank" rel="noreferrer">vite-plugin-pages</a> ⭐ 1.8k — 基于 Vite 的文件系统路由方案，自动根据目录结构生成 Vue Router 配置，支持约定式路由和嵌套路由</li><li><a href="https://github.com/hezhongfeng/vue-page-stack" target="_blank" rel="noreferrer">vue-page-stack</a> ⭐ 355 — Vue SPA 页面导航管理器，模拟浏览器页面栈的返回行为并自动缓存页面状态，适合需要原生 App 体验的复杂应用。</li></ul><h2 id="状态管理插件与扩展" tabindex="-1">状态管理插件与扩展 <a class="header-anchor" href="#状态管理插件与扩展" aria-label="Permalink to “状态管理插件与扩展”">​</a></h2><ul><li><a href="https://github.com/posva/pinia-colada" target="_blank" rel="noreferrer">Pinia Colada</a> ⭐ 2.1k — Vue 的智能数据获取层，基于 Pinia 构建，提供自动缓存、请求去重、乐观更新和完整的 TypeScript 支持，类似 React Query 的 Vue 解决方案</li><li><a href="https://github.com/posva/vue-promised" target="_blank" rel="noreferrer">Vue Promised</a> ⭐ 1.9k — 优雅的 Promise 处理库，提供组合式 API 和组件两种用法，简化异步状态的加载、错误和成功状态管理，内置延迟显示功能</li><li><a href="https://github.com/davestewart/vuex-pathify" target="_blank" rel="noreferrer">Vuex Pathify</a> ⭐ 1.5k — Vuex 的简化工具库，提供智能的 getter/setter 生成和路径语法，大幅减少 Vuex 样板代码，提升开发效率</li><li><a href="https://github.com/vuejs/vue-apollo" target="_blank" rel="noreferrer">vue-apollo</a> ⭐ 5.9k — Vue 官方 Apollo GraphQL 集成库，管理 GraphQL 服务端状态，支持查询、变更、订阅和乐观更新</li><li><a href="https://github.com/vuejs/vue-rx" target="_blank" rel="noreferrer">vue-rx</a> ⭐ 3.3k — Vue 官方 RxJS 集成库，将 Observable 响应式流与 Vue 组件状态管理打通，支持函数式响应式编程</li><li><a href="https://github.com/vuex-orm/vuex-orm" target="_blank" rel="noreferrer">Vuex ORM</a> ⭐ 2.4k — Vuex 生态的 ORM 层，提供模型化数据管理、关系映射（一对一/一对多/多对多）和查询构建器</li><li><a href="https://github.com/wobsoriano/pinia-shared-state" target="_blank" rel="noreferrer">Pinia Shared State</a> ⭐ 1.3k — Pinia 跨标签页/窗口状态同步插件，自动在多个浏览器标签页之间同步 Pinia Store 状态变化，适合多窗口协作场景</li><li><a href="https://github.com/CodeDredd/pinia-orm" target="_blank" rel="noreferrer">Pinia ORM</a> ⭐ 527 — 基于 Vuex ORM Next 的 Pinia 对象关系映射插件，提供 hasMany、belongsTo 等关系定义、查询缓存与类型安全，适合处理大量表格化数据。</li></ul><h2 id="持久化与本地缓存" tabindex="-1">持久化与本地缓存 <a class="header-anchor" href="#持久化与本地缓存" aria-label="Permalink to “持久化与本地缓存”">​</a></h2><ul><li><a href="https://github.com/localForage/localForage" target="_blank" rel="noreferrer">LocalForage</a> ⭐ 25.6k — 离线存储的改进方案，自动选择最佳可用存储后端（IndexedDB/WebSQL/localStorage），提供简洁的异步 API，Vue 项目中持久化的理想基础库</li><li><a href="https://github.com/dexie/Dexie.js" target="_blank" rel="noreferrer">Dexie.js</a> ⭐ 12.5k — IndexedDB 的极简封装库，提供类 SQL 的查询 API、事务支持和表索引，Vue 应用中大规模离线数据存储的首选方案</li><li><a href="https://github.com/unjs/unstorage" target="_blank" rel="noreferrer">Unstorage</a> ⭐ 2.2k — Nuxt 团队出品的通用存储抽象层，统一 localStorage、Redis、Cloudflare KV 等多种存储后端，为 Vue/Nuxt 项目提供一致的缓存接口</li></ul><h2 id="响应式编程集成" tabindex="-1">响应式编程集成 <a class="header-anchor" href="#响应式编程集成" aria-label="Permalink to “响应式编程集成”">​</a></h2><ul><li><a href="https://github.com/ReactiveX/rxjs" target="_blank" rel="noreferrer">RxJS</a> ⭐ 31.9k — 响应式编程标准库，支持 Observable 流、操作符管道和事件组合，可通过 vue-rx 在 Vue 项目中实现数据流驱动架构</li><li><a href="https://github.com/statelyai/xstate" target="_blank" rel="noreferrer">XState Vue</a> ⭐ 28.8k — 基于状态机和状态图的 JavaScript 状态管理库，提供 Vue 集成方案，适合复杂多状态场景（如多步骤表单、审批流程）的状态建模</li></ul><h2 id="撤销重做与操作历史" tabindex="-1">撤销重做与操作历史 <a class="header-anchor" href="#撤销重做与操作历史" aria-label="Permalink to “撤销重做与操作历史”">​</a></h2><ul><li><a href="https://github.com/immerjs/immer" target="_blank" rel="noreferrer">Immer Vue</a> ⭐ 28.5k — 不可变数据结构库，通过 Proxy 产生草稿状态并生成状态快照，配合 Vue 响应式实现可预测的状态变更历史</li></ul>',13)])])}const g=r(i,[["render",o]]);export{f as __pageData,g as default};
